74	        return name.equals(that.name) && count == that.count && indexCount == that.indexCount;
75	    }
76	
77	    @Override
78	    public int hashCode() {
79	        return Objects.hash(name, count, indexCount);
80	    }
81	
82	    @Override
83	    public final XContentBuilder toXContent(XContentBuilder builder, Params params) throws IOException {
84	        builder.startObject();
85	        builder.field("name", name);
86	        builder.field("count", count);
87	        builder.field("index_count", indexCount);
88	        doXContent(builder, params);
89	        builder.endObject();
90	        return builder;
91	    }
92	
93	    protected void doXContent(XContentBuilder builder, Params params) throws IOException {
94	
95	    }
96	
97	    @Override
98	    public String toString() {
99	        return "IndexFeatureStats{" + "name='" + name + '\'' + ", count=" + count + ", indexCount=" + indexCount + '}';
100	    }
101	}
