8	 */
9	
10	package org.elasticsearch.action.admin.cluster.stats;
11	
12	import org.elasticsearch.TransportVersion;
13	import org.elasticsearch.cluster.metadata.IndexMetadata;
14	import org.elasticsearch.cluster.metadata.MappingMetadata;
15	import org.elasticsearch.cluster.metadata.Metadata;
16	import org.elasticsearch.cluster.metadata.ProjectMetadata;
17	import org.elasticsearch.common.Strings;
18	import org.elasticsearch.common.io.stream.StreamInput;
19	import org.elasticsearch.common.io.stream.StreamOutput;
20	import org.elasticsearch.common.io.stream.Writeable;
21	import org.elasticsearch.common.settings.Settings;
22	import org.elasticsearch.features.NodeFeature;
23	import org.elasticsearch.xcontent.ToXContent;
24	import org.elasticsearch.xcontent.ToXContentFragment;
25	import org.elasticsearch.xcontent.XContentBuilder;
26	
27	import java.io.IOException;
28	import java.util.ArrayList;
29	import java.util.Collection;
30	import java.util.Collections;
31	import java.util.Comparator;
32	import java.util.HashMap;
33	import java.util.HashSet;
34	import java.util.IdentityHashMap;
35	import java.util.LinkedHashSet;
36	import java.util.List;
37	import java.util.Map;
38	import java.util.Objects;
39	import java.util.Set;
40	import java.util.TreeMap;
41	
42	/**
43	 * Statistics about analysis usage.
44	 */
45	public final class AnalysisStats implements ToXContentFragment, Writeable {
46	
47	    static final NodeFeature MULTIPLE_SYNONYM_GRAPH_FILTERS_FEATURE = new NodeFeature("cluster.stats.multiple_synonym_graph_filters");
48	
49	    static final TransportVersion MULTIPLE_SYNONYM_GRAPH_FILTERS_VERSION = TransportVersion.fromName(
50	        "cluster_stats_multiple_synonym_graph_filters"
51	    );
52	
53	    private static final String SYNONYM_FILTER_TYPE = "synonym";
54	    private static final String SYNONYM_GRAPH_FILTER_TYPE = "synonym_graph";
55	    private static final Set<String> SYNONYM_FILTER_TYPES = Set.of(SYNONYM_FILTER_TYPE, SYNONYM_GRAPH_FILTER_TYPE);
56	
57	    private static final String SYNONYMS_INLINE_CONFIG = "synonyms";
58	    private static final String SYNONYMS_SET_CONFIG = "synonyms_set";
59	    private static final String SYNONYMS_PATH_CONFIG = "synonyms_path";
60	
61	    static final Map<String, String> SYNONYM_STATS_KEYS_FOR_CONFIG = Map.of(
62	        SYNONYMS_INLINE_CONFIG,
63	        "inline",
64	        SYNONYMS_SET_CONFIG,
65	        "sets",
66	        SYNONYMS_PATH_CONFIG,
67	        "paths"
68	    );
69	
70	    /**
71	     * Create {@link AnalysisStats} from the given cluster state.
72	     */
73	    public static AnalysisStats of(Metadata metadata, Runnable ensureNotCancelled) {
74	        final Map<String, IndexFeatureStats> usedCharFilterTypes = new HashMap<>();
75	        final Map<String, IndexFeatureStats> usedTokenizerTypes = new HashMap<>();
76	        final Map<String, IndexFeatureStats> usedTokenFilterTypes = new HashMap<>();
77	        final Map<String, IndexFeatureStats> usedAnalyzerTypes = new HashMap<>();
78	        final Map<String, IndexFeatureStats> usedBuiltInCharFilters = new HashMap<>();
79	        final Map<String, IndexFeatureStats> usedBuiltInTokenizers = new HashMap<>();
80	        final Map<String, IndexFeatureStats> usedBuiltInTokenFilters = new HashMap<>();
81	        final Map<String, IndexFeatureStats> usedBuiltInAnalyzers = new HashMap<>();
82	        final Map<String, SynonymsStats> usedSynonyms = new HashMap<>();
83	        final Set<String> synonymsIdsUsedInIndices = new HashSet<>();
84	        final Set<String> synonymsIdsUsed = new HashSet<>();
85	        int analyzersWithMultipleSynonymGraphFilters = 0;
86	        int indicesWithMultipleSynonymGraphFilters = 0;
87	
88	        final int mappingCount = metadata.projects().values().stream().mapToInt(p -> p.getMappingsByHash().size()).sum();
89	        final Map<MappingMetadata, Integer> mappingCounts = new IdentityHashMap<>(mappingCount);
90	
91	        for (ProjectMetadata project : metadata.projects().values()) {
92	            for (IndexMetadata indexMetadata : project) {
93	                ensureNotCancelled.run();
94	                if (indexMetadata.isSystem()) {
95	                    // Don't include system indices in statistics about analysis,
96	                    // we care about the user's indices.
97	                    continue;
98	                }
99	
100	                Set<String> indexCharFilters = new HashSet<>();
101	                Set<String> indexTokenizers = new HashSet<>();
102	                Set<String> indexTokenFilters = new HashSet<>();
103	
104	                Set<String> indexAnalyzerTypes = new HashSet<>();
105	                Set<String> indexCharFilterTypes = new HashSet<>();
106	                Set<String> indexTokenizerTypes = new HashSet<>();
107	                Set<String> indexTokenFilterTypes = new HashSet<>();
108	
109	                Settings indexSettings = indexMetadata.getSettings();
110	                Map<String, Settings> analyzerSettings = indexSettings.getGroups("index.analysis.analyzer");
111	                Map<String, Settings> tokenFilterSettings = indexSettings.getGroups("index.analysis.filter");
112	
113	                Set<String> synonymGraphFilterNames = new HashSet<>();
114	                for (Map.Entry<String, Settings> entry : tokenFilterSettings.entrySet()) {
115	                    Settings filterSettings = entry.getValue();
116	                    if (SYNONYM_GRAPH_FILTER_TYPE.equals(filterSettings.get("type"))) {
117	                        synonymGraphFilterNames.add(entry.getKey());
118	                    }
119	                }
120	
121	                usedBuiltInAnalyzers.keySet().removeAll(analyzerSettings.keySet());
122	                boolean indexHasMultipleSynonymGraphFilters = false;
123	                for (Settings analyzerSetting : analyzerSettings.values()) {
124	                    final String analyzerType = analyzerSetting.get("type", "custom");
125	                    IndexFeatureStats stats = usedAnalyzerTypes.computeIfAbsent(analyzerType, IndexFeatureStats::new);
126	                    stats.count++;
127	                    if (indexAnalyzerTypes.add(analyzerType)) {
128	                        stats.indexCount++;
129	                    }
130	
131	                    int synonymGraphFilterCount = 0;
132	                    for (String charFilter : analyzerSetting.getAsList("char_filter")) {
133	                        stats = usedBuiltInCharFilters.computeIfAbsent(charFilter, IndexFeatureStats::new);
134	                        stats.count++;
135	                        if (indexCharFilters.add(charFilter)) {
136	                            stats.indexCount++;
137	                        }
138	                    }
139	
140	                    String tokenizer = analyzerSetting.get("tokenizer");
141	                    if (tokenizer != null) {
142	                        stats = usedBuiltInTokenizers.computeIfAbsent(tokenizer, IndexFeatureStats::new);
143	                        stats.count++;
144	                        if (indexTokenizers.add(tokenizer)) {
145	                            stats.indexCount++;
146	                        }
147	                    }
148	
149	                    for (String filter : analyzerSetting.getAsList("filter")) {
150	                        stats = usedBuiltInTokenFilters.computeIfAbsent(filter, IndexFeatureStats::new);
151	                        stats.count++;
152	                        if (indexTokenFilters.add(filter)) {
153	                            stats.indexCount++;
154	                        }
155	                        if (synonymGraphFilterNames.contains(filter)) {
156	                            synonymGraphFilterCount++;
157	                        }
158	                    }
159	
160	                    if (synonymGraphFilterCount > 1) {
161	                        analyzersWithMultipleSynonymGraphFilters++;
162	                        indexHasMultipleSynonymGraphFilters = true;
163	                    }
164	                }
165	                if (indexHasMultipleSynonymGraphFilters) {
166	                    indicesWithMultipleSynonymGraphFilters++;
167	                }
168	
169	                Map<String, Settings> charFilterSettings = indexSettings.getGroups("index.analysis.char_filter");
170	                usedBuiltInCharFilters.keySet().removeAll(charFilterSettings.keySet());
171	                aggregateAnalysisTypes(charFilterSettings.values(), usedCharFilterTypes, indexCharFilterTypes);
172	
173	                Map<String, Settings> tokenizerSettings = indexSettings.getGroups("index.analysis.tokenizer");
174	                usedBuiltInTokenizers.keySet().removeAll(tokenizerSettings.keySet());
175	                aggregateAnalysisTypes(tokenizerSettings.values(), usedTokenizerTypes, indexTokenizerTypes);
176	
177	                usedBuiltInTokenFilters.keySet().removeAll(tokenFilterSettings.keySet());
178	                aggregateAnalysisTypes(tokenFilterSettings.values(), usedTokenFilterTypes, indexTokenFilterTypes);
179	                aggregateSynonymsStats(
180	                    tokenFilterSettings.values(),
181	                    usedSynonyms,
182	                    indexMetadata.getIndex().getName(),
183	                    synonymsIdsUsed,
184	                    synonymsIdsUsedInIndices
185	                );
186	                countMapping(mappingCounts, indexMetadata);
187	            }
188	        }
189	
190	        for (Map.Entry<MappingMetadata, Integer> mappingAndCount : mappingCounts.entrySet()) {
191	            ensureNotCancelled.run();
192	            Set<String> indexAnalyzers = new HashSet<>();
193	            final int count = mappingAndCount.getValue();
194	            MappingVisitor.visitMapping(mappingAndCount.getKey().getSourceAsMap(), (field, fieldMapping) -> {
195	                for (String key : new String[] { "analyzer", "search_analyzer", "search_quote_analyzer" }) {
196	                    Object analyzerO = fieldMapping.get(key);
197	                    if (analyzerO != null) {
198	                        final String analyzer = analyzerO.toString();
199	                        IndexFeatureStats stats = usedBuiltInAnalyzers.computeIfAbsent(analyzer, IndexFeatureStats::new);
200	                        stats.count += count;
201	                        if (indexAnalyzers.add(analyzer)) {
202	                            stats.indexCount += count;
203	                        }
204	                    }
205	                }
206	            });
207	        }
208	
209	        return new AnalysisStats(
210	            usedCharFilterTypes.values(),
211	            usedTokenizerTypes.values(),
212	            usedTokenFilterTypes.values(),
213	            usedAnalyzerTypes.values(),
214	            usedBuiltInCharFilters.values(),
215	            usedBuiltInTokenizers.values(),
216	            usedBuiltInTokenFilters.values(),
217	            usedBuiltInAnalyzers.values(),
218	            usedSynonyms,
219	            analyzersWithMultipleSynonymGraphFilters,
220	            indicesWithMultipleSynonymGraphFilters
221	        );
222	    }
223	
224	    public static void countMapping(Map<MappingMetadata, Integer> mappingCounts, IndexMetadata indexMetadata) {
225	        final MappingMetadata mappingMetadata = indexMetadata.mapping();
226	        if (mappingMetadata == null) {
227	            return;
228	        }
229	        mappingCounts.merge(mappingMetadata, 1, Integer::sum);
230	    }
231	
232	    private static void aggregateAnalysisTypes(
233	        Collection<Settings> settings,
234	        Map<String, IndexFeatureStats> stats,
235	        Set<String> indexTypes
236	    ) {
237	        for (Settings analysisComponentSettings : settings) {
238	            final String type = analysisComponentSettings.get("type");
239	            if (type != null) {
240	                IndexFeatureStats s = stats.computeIfAbsent(type, IndexFeatureStats::new);
241	                s.count++;
242	                if (indexTypes.add(type)) {
243	                    s.indexCount++;
244	                }
245	            }
246	        }
247	    }
248	
249	    private static void aggregateSynonymsStats(
250	        Collection<Settings> filterSettings,
251	        Map<String, SynonymsStats> synonymsStats,
252	        String indexName,
253	        Set<String> synonymsIdsUsed,
254	        Set<String> synonymIdsUsedInIndices
255	    ) {
256	        for (Settings filterComponentSettings : filterSettings) {
257	            final String type = filterComponentSettings.get("type");
258	            if (SYNONYM_FILTER_TYPES.contains(type)) {
259	                boolean isInline = false;
260	                String synonymRuleType = SYNONYMS_SET_CONFIG;
261	                // Avoid requesting settings for synonyms rule type, as it transforms to string a potentially large number of synonym rules
262	                String synonymId = filterComponentSettings.get(synonymRuleType);
263	                if (synonymId == null) {
264	                    synonymRuleType = SYNONYMS_PATH_CONFIG;
265	                    synonymId = filterComponentSettings.get(synonymRuleType);
266	                }
267	                if (synonymId == null) {
268	                    synonymRuleType = SYNONYMS_INLINE_CONFIG;
269	                    isInline = true;
270	                }
271	                SynonymsStats stat = synonymsStats.computeIfAbsent(
272	                    SYNONYM_STATS_KEYS_FOR_CONFIG.get(synonymRuleType),
273	                    id -> new SynonymsStats()
274	                );
275	                if (synonymIdsUsedInIndices.add(synonymRuleType + indexName)) {
276	                    stat.indexCount++;
277	                }
278	                if (isInline || synonymsIdsUsed.add(synonymRuleType + synonymId)) {
279	                    stat.count++;
280	                }
281	            }
282	        }
283	    }
284	
285	    private static Set<IndexFeatureStats> sort(Collection<IndexFeatureStats> set) {
286	        List<IndexFeatureStats> list = new ArrayList<>(set);
287	        list.sort(Comparator.comparing(IndexFeatureStats::getName));
288	        return Collections.unmodifiableSet(new LinkedHashSet<>(list));
289	    }
290	
291	    private final Set<IndexFeatureStats> usedCharFilters, usedTokenizers, usedTokenFilters, usedAnalyzers;
292	    private final Set<IndexFeatureStats> usedBuiltInCharFilters, usedBuiltInTokenizers, usedBuiltInTokenFilters, usedBuiltInAnalyzers;
293	
294	    private final Map<String, SynonymsStats> usedSynonyms;
295	
296	    /**
297	     * Number of analyzers across the cluster whose filter chain contains more than one synonym_graph filter.
298	     */
299	    private final int analyzersWithMultipleSynonymGraphFilters;
300	
301	    /**
302	     * Number of indices that contain at least one analyzer with more than one synonym_graph filter.
303	     */
304	    private final int indicesWithMultipleSynonymGraphFilters;
305	
306	    AnalysisStats(
307	        Collection<IndexFeatureStats> usedCharFilters,
308	        Collection<IndexFeatureStats> usedTokenizers,
309	        Collection<IndexFeatureStats> usedTokenFilters,
310	        Collection<IndexFeatureStats> usedAnalyzers,
311	        Collection<IndexFeatureStats> usedBuiltInCharFilters,
312	        Collection<IndexFeatureStats> usedBuiltInTokenizers,
313	        Collection<IndexFeatureStats> usedBuiltInTokenFilters,
314	        Collection<IndexFeatureStats> usedBuiltInAnalyzers,
315	        Map<String, SynonymsStats> usedSynonyms,
316	        int analyzersWithMultipleSynonymGraphFilters,
317	        int indicesWithMultipleSynonymGraphFilters
318	    ) {
319	        this.usedCharFilters = sort(usedCharFilters);
320	        this.usedTokenizers = sort(usedTokenizers);
321	        this.usedTokenFilters = sort(usedTokenFilters);
322	        this.usedAnalyzers = sort(usedAnalyzers);
323	        this.usedBuiltInCharFilters = sort(usedBuiltInCharFilters);
324	        this.usedBuiltInTokenizers = sort(usedBuiltInTokenizers);
325	        this.usedBuiltInTokenFilters = sort(usedBuiltInTokenFilters);
326	        this.usedBuiltInAnalyzers = sort(usedBuiltInAnalyzers);
327	        this.usedSynonyms = new TreeMap<>(usedSynonyms);
328	        this.analyzersWithMultipleSynonymGraphFilters = analyzersWithMultipleSynonymGraphFilters;
329	        this.indicesWithMultipleSynonymGraphFilters = indicesWithMultipleSynonymGraphFilters;
330	    }
331	
332	    public AnalysisStats(StreamInput input) throws IOException {
333	        usedCharFilters = Collections.unmodifiableSet(new LinkedHashSet<>(input.readCollectionAsList(IndexFeatureStats::new)));
334	        usedTokenizers = Collections.unmodifiableSet(new LinkedHashSet<>(input.readCollectionAsList(IndexFeatureStats::new)));
335	        usedTokenFilters = Collections.unmodifiableSet(new LinkedHashSet<>(input.readCollectionAsList(IndexFeatureStats::new)));
336	        usedAnalyzers = Collections.unmodifiableSet(new LinkedHashSet<>(input.readCollectionAsList(IndexFeatureStats::new)));
337	        usedBuiltInCharFilters = Collections.unmodifiableSet(new LinkedHashSet<>(input.readCollectionAsList(IndexFeatureStats::new)));
338	        usedBuiltInTokenizers = Collections.unmodifiableSet(new LinkedHashSet<>(input.readCollectionAsList(IndexFeatureStats::new)));
339	        usedBuiltInTokenFilters = Collections.unmodifiableSet(new LinkedHashSet<>(input.readCollectionAsList(IndexFeatureStats::new)));
340	        usedBuiltInAnalyzers = Collections.unmodifiableSet(new LinkedHashSet<>(input.readCollectionAsList(IndexFeatureStats::new)));
341	        usedSynonyms = input.readImmutableMap(SynonymsStats::new);
342	        if (input.getTransportVersion().supports(MULTIPLE_SYNONYM_GRAPH_FILTERS_VERSION)) {
343	            analyzersWithMultipleSynonymGraphFilters = input.readVInt();
344	            indicesWithMultipleSynonymGraphFilters = input.readVInt();
345	        } else {
346	            analyzersWithMultipleSynonymGraphFilters = 0;
347	            indicesWithMultipleSynonymGraphFilters = 0;
348	        }
349	    }
350	
351	    @Override
352	    public void writeTo(StreamOutput out) throws IOException {
353	        out.writeCollection(usedCharFilters);
354	        out.writeCollection(usedTokenizers);
355	        out.writeCollection(usedTokenFilters);
356	        out.writeCollection(usedAnalyzers);
357	        out.writeCollection(usedBuiltInCharFilters);
358	        out.writeCollection(usedBuiltInTokenizers);
359	        out.writeCollection(usedBuiltInTokenFilters);
360	        out.writeCollection(usedBuiltInAnalyzers);
361	        out.writeMap(usedSynonyms, StreamOutput::writeWriteable);
362	        if (out.getTransportVersion().supports(MULTIPLE_SYNONYM_GRAPH_FILTERS_VERSION)) {
363	            out.writeVInt(analyzersWithMultipleSynonymGraphFilters);
364	            out.writeVInt(indicesWithMultipleSynonymGraphFilters);
365	        }
366	    }
367	
368	    /**
369	     * Return the set of used char filters in the cluster.
370	     */
371	    public Set<IndexFeatureStats> getUsedCharFilterTypes() {
372	        return usedCharFilters;
373	    }
374	
375	    /**
376	     * Return the set of used tokenizers in the cluster.
377	     */
378	    public Set<IndexFeatureStats> getUsedTokenizerTypes() {
379	        return usedTokenizers;
380	    }
381	
382	    /**
383	     * Return the set of used token filters in the cluster.
384	     */
385	    public Set<IndexFeatureStats> getUsedTokenFilterTypes() {
386	        return usedTokenFilters;
387	    }
388	
389	    /**
390	     * Return the set of used analyzers in the cluster.
391	     */
392	    public Set<IndexFeatureStats> getUsedAnalyzerTypes() {
393	        return usedAnalyzers;
394	    }
395	
396	    /**
397	     * Return the set of used built-in char filters in the cluster.
398	     */
399	    public Set<IndexFeatureStats> getUsedBuiltInCharFilters() {
400	        return usedBuiltInCharFilters;
401	    }
402	
403	    /**
404	     * Return the set of used built-in tokenizers in the cluster.
405	     */
406	    public Set<IndexFeatureStats> getUsedBuiltInTokenizers() {
407	        return usedBuiltInTokenizers;
408	    }
409	
410	    /**
411	     * Return the set of used built-in token filters in the cluster.
412	     */
413	    public Set<IndexFeatureStats> getUsedBuiltInTokenFilters() {
414	        return usedBuiltInTokenFilters;
415	    }
416	
417	    /**
418	     * Return the set of used built-in analyzers in the cluster.
419	     */
420	    public Set<IndexFeatureStats> getUsedBuiltInAnalyzers() {
421	        return usedBuiltInAnalyzers;
422	    }
423	
424	    public Map<String, SynonymsStats> getUsedSynonyms() {
425	        return usedSynonyms;
426	    }
427	
428	    /**
429	     * Return the number of analyzers across the cluster whose filter chain contains more than one synonym_graph filter.
430	     */
431	    public int getAnalyzersWithMultipleSynonymGraphFilters() {
432	        return analyzersWithMultipleSynonymGraphFilters;
433	    }
434	
435	    /**
436	     * Return the number of indices that contain at least one analyzer with more than one synonym_graph filter.
437	     */
438	    public int getIndicesWithMultipleSynonymGraphFilters() {
439	        return indicesWithMultipleSynonymGraphFilters;
440	    }
441	
442	    @Override
443	    public boolean equals(Object o) {
444	        if (this == o) return true;
445	        if (o == null || getClass() != o.getClass()) return false;
446	        AnalysisStats that = (AnalysisStats) o;
447	        return analyzersWithMultipleSynonymGraphFilters == that.analyzersWithMultipleSynonymGraphFilters
448	            && indicesWithMultipleSynonymGraphFilters == that.indicesWithMultipleSynonymGraphFilters
449	            && Objects.equals(usedCharFilters, that.usedCharFilters)
450	            && Objects.equals(usedTokenizers, that.usedTokenizers)
451	            && Objects.equals(usedTokenFilters, that.usedTokenFilters)
452	            && Objects.equals(usedAnalyzers, that.usedAnalyzers)
453	            && Objects.equals(usedBuiltInCharFilters, that.usedBuiltInCharFilters)
454	            && Objects.equals(usedBuiltInTokenizers, that.usedBuiltInTokenizers)
455	            && Objects.equals(usedBuiltInTokenFilters, that.usedBuiltInTokenFilters)
456	            && Objects.equals(usedBuiltInAnalyzers, that.usedBuiltInAnalyzers)
457	            && Objects.equals(usedSynonyms, that.usedSynonyms);
458	    }
459	
460	    @Override
461	    public int hashCode() {
462	        return Objects.hash(
463	            usedCharFilters,
464	            usedTokenizers,
465	            usedTokenFilters,
466	            usedAnalyzers,
467	            usedBuiltInCharFilters,
468	            usedBuiltInTokenizers,
469	            usedBuiltInTokenFilters,
470	            usedBuiltInAnalyzers,
471	            usedSynonyms,
472	            analyzersWithMultipleSynonymGraphFilters,
473	            indicesWithMultipleSynonymGraphFilters
474	        );
475	    }
476	
477	    private static void toXContentCollection(XContentBuilder builder, Params params, String name, Collection<? extends ToXContent> coll)
478	        throws IOException {
479	        builder.startArray(name);
